package br.com.pelotavision;
import static org.junit.Assert.*;import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.android.controller.ActivityController;import org.robolectric.annotation.*;import android.app.AlertDialog;import android.os.Looper;import android.view.*;import android.widget.*;import java.util.*;import java.lang.reflect.*;import org.json.*;
@RunWith(RobolectricTestRunner.class) @Config(sdk=33,manifest=Config.NONE)
public class DetectionSuggestionTest {
 static PelletDetector.Result result(double... diameters){List<PelletDetector.Detection> ds=new ArrayList<>();for(int i=0;i<diameters.length;i++)ds.add(EllipseWorkflowTest.ellipse(30+70*(i%8),30+70*(i/8),diameters[i]/2,diameters[i]/2,0,false,false));return new PelletDetector.Result(ds,640,480,ds.size(),1,false,"gradient_circle_CLAHE_v1+ellipse_boundary_v1");}
 static DetectionAssessment.Context ctx(Granulometry.Settings scale){return new DetectionAssessment.Context(scale,1280,960,null,5);}
 static DetectionTuner.Report report(PelletDetector.Result... results){List<DetectionTuner.Trial> trials=new ArrayList<>();for(int i=0;i<results.length;i++)trials.add(new DetectionTuner.Trial(new DetectionTuner.Option(3,55+20*i,false),results[i],null,1,null,0));return new DetectionTuner.Report(trials,results.length,30,false,false,ctx(null)).rank(ctx(null));}
 @Test public void weibullFitUsesObservedValuesAndIsScaleInvariant(){List<Double> data=new ArrayList<>(),scaled=new ArrayList<>();for(int i=0;i<200;i++){double d=12*Math.pow(-Math.log(1-(i+.5)/200),1./5);data.add(d);scaled.add(d*3.7);}DetectionAssessment.Weibull fit=DetectionAssessment.weibull(data),other=DetectionAssessment.weibull(scaled);assertTrue(fit.available());assertEquals(5,fit.shape,.06);assertEquals(12,fit.scale,.02);assertTrue(fit.ks<.008);assertEquals(fit.shape,other.shape,1e-10);assertEquals(fit.scale*3.7,other.scale,1e-10);assertEquals(fit.ks,other.ks,1e-10);assertFalse(DetectionAssessment.weibull(Arrays.asList(10.,12.)).available());assertFalse(DetectionAssessment.weibull(Collections.nCopies(20,12.)).available());}
 @Test public void fiveMmIsInactiveWithoutIndependentScaleAndNeverFilters(){PelletDetector.Result r=result(20,40,60,80);assertFalse(ctx(null).minimumActive());assertEquals(0,DetectionAssessment.measure(r,ctx(null)).belowMinimum);Granulometry.Settings estimate=Granulometry.Settings.estimatedMean(12,1,true,false);assertFalse(ctx(estimate).minimumActive());Granulometry.Distribution locked=Granulometry.compute(Arrays.asList(new Granulometry.Item(20,false,false),new Granulometry.Item(80,false,false)),estimate,1280,960,640,480);assertFalse(ctx(locked.settings).minimumActive());DetectionAssessment.Metrics m=DetectionAssessment.measure(r,ctx(new Granulometry.Settings(20,1,true,false)));assertEquals(2,m.belowMinimum);assertEquals(4,m.total);assertEquals(4,r.circles.size());assertTrue(ctx(new Granulometry.Settings(20,1,true,false)).minimumActive());assertFalse(new DetectionAssessment.Context(new Granulometry.Settings(20,1,true,false),1280,960,null,0).minimumActive());}
 @Test public void reRankingAfterCalibrationChangesSuggestionWithoutChangingDiameters(){PelletDetector.Result manySmall=result(20,22,24,26,28,30,32,34,36,38,40,60),real=result(60,65,70,75,80,85);DetectionTuner.Report original=report(manySmall,real);assertSame(manySmall,original.best().result);DetectionTuner.Report physical=original.rank(ctx(new Granulometry.Settings(20,1,true,false)));assertSame(real,physical.best().result);assertSame(manySmall,physical.trials.get(0).result);assertEquals(12,physical.trials.get(0).result.circles.size());assertEquals(20,manySmall.circles.get(0).radius*2,0);}
 @Test public void roiAndExcludedReferenceFootprintAffectScoringOnly(){PelletDetector.Result r=result(20,60,60);ObjectCalibration.Reference ref=ObjectCalibration.select(r.circles.get(0),1,1,ObjectCalibration.Measure.STANDARD_SPHERE,2,true,1280,960,640,480);DetectionAssessment.Context context=ctx(Granulometry.Settings.selectedObject(ref,1,true,false));assertEquals(2,DetectionAssessment.measure(r,context).total);assertEquals(0,DetectionAssessment.measure(r,context).belowMinimum);InterestRegion roi=new InterestRegion(InterestRegion.Shape.RECTANGLE,65,0,135,65);assertEquals(1,DetectionAssessment.measure(r,new DetectionAssessment.Context(null,1280,960,roi,5)).total);assertEquals(3,r.circles.size());assertEquals(1,ref.fullImageId);}
 @Test public void badGeometryCannotWinFromRosinRammlerOrCountAlone(){PelletDetector.Result empty=result(),one=result(40);List<PelletDetector.Detection> bad=new ArrayList<>();for(int i=0;i<50;i++)bad.add(new PelletDetector.Detection(i*5,10,20,400*Math.PI,1,false,false));PelletDetector.Result noisy=new PelletDetector.Result(bad,640,480,50,1,false);DetectionTuner.Report scores=report(noisy,one,empty);assertSame(one,scores.best().result);assertTrue(scores.weak());assertEquals(0,scores.trials.get(0).score,0);assertTrue(report(empty).weak());assertEquals(0,report(empty).best().score,0);}
 @Test public void agreementIsOneToOneAndOptionsCoverProfilesSensitivities(){assertEquals(1,DetectionAssessment.agreement(result(40,40),result(40,40)),0);assertEquals(2./3,DetectionAssessment.agreement(result(40),result(40,40)),0);List<DetectionTuner.Option> options=DetectionTuner.options(new DetectionTuner.Option(3,75,false));assertEquals(24,options.size());Set<String> ids=new HashSet<>();for(DetectionTuner.Option o:options)assertTrue(ids.add(o.id));assertEquals(25,DetectionTuner.options(new DetectionTuner.Option(1,80,true)).size());}
 @Test public void exportDisclosesAssumptionsAndAppliedVersusRecommended()throws Exception{DetectionTuner.Report report=report(result(20,22,24,26,28,30,32,34,36,38,40,60),result(60,65,70,75,80,85)).rank(ctx(new Granulometry.Settings(20,1,true,false)));JSONObject j=(JSONObject)ResultSaver.suggestionJson(report,report.trials.get(0).option);assertTrue(j.getBoolean("minimum_rule_active"));assertFalse(j.getBoolean("minimum_rule_filters_detections"));assertFalse(j.getBoolean("diameters_modified_to_fit_distribution"));assertNotEquals(j.getString("applied_option_id"),j.getString("recommended_option_id"));assertEquals(2,j.getJSONArray("trials").length());}
 static void call(MainActivity a,String name)throws Exception{Method m=MainActivity.class.getDeclaredMethod(name);m.setAccessible(true);m.invoke(a);Shadows.shadowOf(Looper.getMainLooper()).idle();}
 static Object get(MainActivity a,String name)throws Exception{Field f=MainActivity.class.getDeclaredField(name);f.setAccessible(true);return f.get(a);}static void set(MainActivity a,String name,Object value)throws Exception{Field f=MainActivity.class.getDeclaredField(name);f.setAccessible(true);f.set(a,value);}
 @Test public void settingsValidateMinimumAndPersistAutoSwitch()throws Exception{try(ActivityController<MainActivity> ctl=Robolectric.buildActivity(MainActivity.class).setup()){MainActivity a=ctl.get();assertEquals(true,get(a,"autoSuggest"));assertEquals(5.,(Double)get(a,"minimumExpectedMm"),0);call(a,"showAdjustments");AlertDialog d=org.robolectric.shadows.ShadowAlertDialog.getLatestAlertDialog();View root=d.getWindow().getDecorView();EditText minimum=root.findViewWithTag("minimum_expected_mm");minimum.setText("NaN");d.getButton(AlertDialog.BUTTON_POSITIVE).performClick();assertTrue(d.isShowing());assertEquals(5.,(Double)get(a,"minimumExpectedMm"),0);minimum.setText("5,5");((CheckBox)root.findViewWithTag("auto_suggest")).setChecked(false);d.getButton(AlertDialog.BUTTON_POSITIVE).performClick();assertFalse(d.isShowing());assertEquals(false,get(a,"autoSuggest"));assertEquals(5.5,(Double)get(a,"minimumExpectedMm"),0);call(a,"restoreParameters");assertEquals(false,get(a,"autoSuggest"));assertEquals(5.5,(Double)get(a,"minimumExpectedMm"),0);}}
 @Test public void comparisonAfterCalibrationIsInformationalAndKeepsReference()throws Exception{try(ActivityController<MainActivity> ctl=Robolectric.buildActivity(MainActivity.class).setup()){MainActivity a=ctl.get();ObjectCalibrationTest.setup(a);DetectionTuner.Report report=report(result(20,22,24,26,28,30,32,34,36,38,40,60),result(60,65,70,75,80,85));set(a,"photoSuggestions",report);set(a,"photoOption",report.trials.get(0).option);Granulometry.Settings scale=new Granulometry.Settings(20,1,true,false);set(a,"scaleSettings",scale);PelletDetector.Result before=(PelletDetector.Result)get(a,"photoAllResult");set(a,"suggestionWindow",get(a,"displayWindow"));call(a,"showSuggestions");AlertDialog d=org.robolectric.shadows.ShadowAlertDialog.getLatestAlertDialog();assertNotNull(d.getWindow().getDecorView().findViewWithTag("suggestion_options"));assertSame(before,get(a,"photoAllResult"));assertSame(scale,get(a,"scaleSettings"));d.getButton(AlertDialog.BUTTON_NEGATIVE).performClick();Shadows.shadowOf(Looper.getMainLooper()).idle();assertSame(before,get(a,"photoAllResult"));assertSame(scale,get(a,"scaleSettings"));call(a,"releasePreviousPhoto");assertNull(get(a,"photoSuggestions"));}}
}
